function openMobileSidebar(){const sidebar=document.getElementById('sidebar');const overlay=document.getElementById('sidebarOverlay');if(sidebar&&overlay){sidebar.classList.add('mobile-open');overlay.classList.add('active');document.body.style.overflow='hidden';}}
function closeMobileSidebar(){const sidebar=document.getElementById('sidebar');const overlay=document.getElementById('sidebarOverlay');if(sidebar&&overlay){sidebar.classList.remove('mobile-open');overlay.classList.remove('active');document.body.style.overflow='';}}
window.addEventListener('resize',function(){if(window.innerWidth>768){closeMobileSidebar();}});function handleSearch(event){if(event.key==='Enter'){const query=event.target.value.trim();if(query){window.location.href=`/search/?q=${encodeURIComponent(query)}`;}}}
function toggleNotifications(event){if(event){event.preventDefault();event.stopPropagation();}
const dropdown=document.getElementById('notificationDropdown');const isShowing=dropdown.classList.contains('show');if(!isShowing){dropdown.classList.add('show');loadRecentNotifications();}else{dropdown.classList.remove('show');}}
function loadRecentNotifications(){const list=document.getElementById('notificationList');list.innerHTML='<div class="notification-loading">Loading...</div>';fetch('/notifications/recent/').then(response=>response.json()).then(data=>{const badge=document.getElementById('notificationBadge');if(data.unread_count>0){badge.textContent=data.unread_count>99?'99+':data.unread_count;badge.style.display='flex';}else{badge.style.display='none';}
if(data.notifications&&data.notifications.length>0){list.innerHTML=data.notifications.map(n=>`
                            <div class="notification-item ${n.is_read ? '' : 'unread'}" onclick="handleNotificationClick(event, '${n.link || '#'}', ${n.id})">
                                <div class="notification-item-content">
                                    <h4 class="notification-item-title">${n.title}</h4>
                                    <p class="notification-item-message">${n.message}</p>
                                    <span class="notification-item-time">${n.created_at}</span>
                                </div>
                                ${n.is_read ? '' : '<span class="unread-dot"></span>'}
                            </div>
                        `).join('');}else{list.innerHTML='<div class="notification-empty">No new notifications</div>';}}).catch(error=>{console.error('Error loading notifications:',error);list.innerHTML='<div class="notification-error">Failed to load notifications</div>';});}
function handleNotificationClick(event,link,id){if(event)event.stopPropagation();fetch(`/notifications/mark-read/${id}/`,{method:'POST',headers:{'X-CSRFToken':getCookie('csrftoken'),}}).finally(()=>{if(link&&link!=='#'){window.location.href=link;}else{loadRecentNotifications();updateNotificationCount();}});}
function markAllNotificationsRead(event){if(event)event.stopPropagation();fetch('/notifications/mark-all-read/',{method:'POST',headers:{'X-CSRFToken':getCookie('csrftoken'),}}).then(response=>response.json()).then(data=>{if(data.status==='success'){loadRecentNotifications();updateNotificationCount();}}).catch(error=>console.error('Error marking all as read:',error));}
function getCookie(name){let cookieValue=null;if(document.cookie&&document.cookie!==''){const cookies=document.cookie.split(';');for(let i=0;i<cookies.length;i++){const cookie=cookies[i].trim();if(cookie.substring(0,name.length+1)===(name+'=')){cookieValue=decodeURIComponent(cookie.substring(name.length+1));break;}}}
return cookieValue;}
document.addEventListener('click',function(event){const dropdown=document.getElementById('notificationDropdown');const btn=document.getElementById('notificationBtn');if(dropdown&&!dropdown.contains(event.target)&&!btn.contains(event.target)){dropdown.classList.remove('show');}});function updateNotificationCount(count=null){const badge=document.getElementById('notificationBadge');if(!badge)return;if(count!==null){if(count>0){badge.textContent=count>99?'99+':count;badge.style.display='flex';}else{badge.style.display='none';}
return;}
fetch('/notifications/unread-count/').then(response=>response.json()).then(data=>{if(data.count>0){badge.textContent=data.count>99?'99+':data.count;badge.style.display='flex';}else{badge.style.display='none';}}).catch(error=>console.warn('Error fetching notification count:',error));}
function connectNotificationWS(){const protocol=window.location.protocol==='https:'?'wss:':'ws:';const wsUrl=`${protocol}//${window.location.host}/ws/notifications/`;const socket=new WebSocket(wsUrl);socket.onmessage=function(e){const data=JSON.parse(e.data);console.log('Notification received:',data);if(data.type==='new_message'){showToast(`Message from ${data.sender}`,data.message,'info');updateNotificationCount();if(window.location.pathname.includes('/inbox/')||window.location.pathname.includes('/conversation/')){refreshCurrentPage();}
window.dispatchEvent(new CustomEvent('new_message',{detail:data}));}else if(data.type==='meeting_started'){showToast(`Class Started!`,`${data.title} is now LIVE.`,'success');updateNotificationCount();refreshCurrentPage();window.dispatchEvent(new CustomEvent('meeting_state_change',{detail:data}));}else if(data.type==='live_status_change'){if(data.status==='started'){showToast(`Live Lecture!`,`${data.teacher_name} is now live in ${data.camera_name}`,'success');}
if(!window.location.pathname.includes('/meetings/join/')&&!window.location.pathname.includes('/cameras/teacher/')){refreshCurrentPage();}
window.dispatchEvent(new CustomEvent('live_status_change',{detail:data}));}else if(data.type==='classroom_request'){showToast(`New Join Request`,`${data.student_name} wants to join ${data.classroom_title}`,'info');updateNotificationCount();if(window.location.pathname.includes('/classrooms/')||window.location.pathname.includes('/manage/')){refreshCurrentPage();}}else if(data.type==='classroom_approved'){showToast(`Request Approved!`,`You have been added to ${data.classroom_title}`,'success');updateNotificationCount();refreshCurrentPage();}else if(data.type==='meeting_scheduled'){showToast(`New Meeting`,`A new meeting "${data.title}" has been scheduled.`,'info');updateNotificationCount();if(window.location.pathname.includes('/dashboard/')||window.location.pathname==='/'){refreshCurrentPage();}}else if(data.type==='meeting_cancelled'){showToast(`Meeting Cancelled`,`"${data.title}" has been cancelled.`,'warning');updateNotificationCount();refreshCurrentPage();}else if(data.type==='classroom_denied'){showToast(`Join Request Denied`,`Your request for ${data.classroom_title} was denied.`,'error');updateNotificationCount();refreshCurrentPage();}else if(data.type==='classroom_removed'){showToast(`Removed from Class`,`You were removed from ${data.classroom_title}.`,'warning');updateNotificationCount();refreshCurrentPage();}else if(data.type==='student_joined'){showToast(`Student Joined`,`${data.student_name} joined ${data.classroom_title}`,'success');updateNotificationCount();if(window.location.pathname.includes('/classrooms/view/')){refreshCurrentPage();}}};function refreshCurrentPage(){if(window.room&&window.room.state==='connected'){console.log('Skipping auto-refresh: Active meeting session detected.');return;}
if(window.isStreaming||window.isRecording){console.log('Skipping auto-refresh: Active camera session detected.');return;}
console.log('Smoothing refreshing page due to real-time update...');if(typeof Turbo!=='undefined'){Turbo.visit(window.location.href,{action:'replace'});}else{window.location.reload();}}
socket.onclose=function(e){console.log('Notification socket closed. Reconnecting in 3 seconds...');setTimeout(connectNotificationWS,3000);};socket.onerror=function(err){console.error('Notification socket error:',err);socket.close();};}
function showToast(title,message,type='info'){const container=document.getElementById('toastContainer')||createToastContainer();const toast=document.createElement('div');toast.className=`custom-toast ${type}`;toast.innerHTML=`
                <div class="toast-content">
                    <strong>${title}</strong>
                    <p>${message}</p>
                </div>
                <button class="toast-close" onclick="this.parentElement.remove()">&times;</button>
            `;container.appendChild(toast);setTimeout(()=>{toast.classList.add('fade-out');setTimeout(()=>toast.remove(),500);},5000);}
function createToastContainer(){const container=document.createElement('div');container.id='toastContainer';container.className='toast-container';document.body.appendChild(container);return container;}
document.addEventListener('DOMContentLoaded',function(){const savedTheme=localStorage.getItem('theme');if(savedTheme==='dark'){document.body.classList.add('dark-mode');updateThemeIcons(true);}
updateNotificationCount();connectNotificationWS();});function toggleTheme(){const isDark=document.body.classList.toggle('dark-mode');localStorage.setItem('theme',isDark?'dark':'light');updateThemeIcons(isDark);}
function updateThemeIcons(isDark){const sunIcon=document.getElementById('sunIcon');const moonIcon=document.getElementById('moonIcon');if(isDark){sunIcon.style.display='block';moonIcon.style.display='none';}else{sunIcon.style.display='none';moonIcon.style.display='block';}};